<?php get_header();lw_page_hero(is_home()?'Latest Articles':(is_search()?'Search Results':get_the_archive_title()));?>
<section class="lw-section"><div class="lw-container"><div class="lw-article-grid">
<?php if(have_posts()):while(have_posts()):the_post();?><article <?php post_class('lw-article-card'); ?>><a class="lw-article-cover" href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail()) the_post_thumbnail('medium_large');else echo '<span class="lw-placeholder-article">LUXURY JOURNAL</span>'; ?></a><div class="lw-article-text"><span class="lw-date"><?php echo esc_html(get_the_date()); ?></span><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(get_the_excerpt()); ?></p><a class="lw-text-link" href="<?php the_permalink(); ?>">Read More ↗</a></div></article><?php endwhile;else: ?><p>No articles found.</p><?php endif; ?></div><nav class="lw-pagination" aria-label="Pages"><?php the_posts_pagination(); ?></nav></div></section><?php get_footer(); ?>
